        [HttpPost]
        public ActionResult BindModule_DD(string Year)
        {
            var DD_List = ABE.obj_dd_wsp_module.Where(x => x.fin_year == Year).ToList();
            return Json(DD_List);
        }

        [HttpPost]
        public ActionResult BindSubModule_DD(int module_val, string Year)
        {
            var DD_List = ABE.obj_dd_wsp_submodule.Where(x => x.module_val == module_val && x.fin_year == Year).ToList().OrderBy(x => x.sub_module_val);
            return Json(DD_List);
        }
